func OptionalStringFromMap(in map[string]interface{}, name string, setFn func(v string)) error {
	value, ok := in[name]
	if !ok {
		return nil
	}
	asString, ok := value.(string)
	if !ok {
		return nil  // <-- BUG: silently ignores null instead of erroring
	}
	setFn(asString)
	return nil
}

